# ── Cache-bust for bind-mounted patched JS chunks ─────────────────────
# Superset serves /static/assets/* with Cache-Control: public, max-age=31536000
# (1 year). When we bind-mount a patched chunk at the same filename, the hash
# in the URL is unchanged, so browsers serve the cached old content forever.
# This after_request hook overrides Cache-Control for the specific patched
# files only — every other asset keeps its long cache for performance.
_PATCHED_CHUNK_PATHS = {
    "/static/assets/3871.c687a6d83eaaee71a216.entry.js",
    # Loader gif paths: drop the 1-yr immutable cache so the <img>'s own src
    # revalidates to the bind-mounted airplane (no stock symbol left to flash).
    "/static/assets/loading.cff8a5da..gif",
    "/static/assets/images/loading.gif",
}

def _no_cache_for_patched_chunks(response):
    from flask import request
    if request.path in _PATCHED_CHUNK_PATHS:
        response.headers["Cache-Control"] = "no-cache, must-revalidate"
        response.headers.pop("Expires", None)
    return response

# == CPI tenant-aware loading animation (airline airplane / cruise ship) ======
# Injects a <style> on the standalone Chart View (/explore + standalone) and the
# Embedded SDK dashboard pages (/embedded/<uuid>) overriding Superset's chart +
# filter loader <img class="loading"> with a tenant-typed animation via a base64
# data: URI (present at first paint; no network fetch). Airline -> airplane,
# cruise (FJL) -> ship. Both gifs are inlined as literals (prod serves the stock
# loader; nothing is bind-mounted). Tenant type is derived server-side from the
# metadata DB: /explore?slice_id -> slices.perm marker; /embedded/<uuid> ->
# embedded_dashboards.dashboard_id (FJL = 2; FJL perms contain "fjl"/"cfl").
# Every DB lookup is cached + try/except; ANY failure falls back to airplane.
# CSP: prod Talisman allows inline <style> (style-src 'unsafe-inline') and
# data: images (img-src data:), so this injection is policy-compliant.
_CPI_AIRPLANE_DATA_URI = "data:image/gif;base64,"
_CPI_SHIP_DATA_URI = "data:image/gif;base64,"
_CPI_CRUISE_DASHBOARD_IDS = {2}
_CPI_CRUISE_MARKERS = ("fjl", "cfl")

_cpi_slice_cruise_cache = {}
_cpi_embed_uuid_map = None  # normalized-hex uuid -> dashboard_id (loaded once)

def _cpi_md_execute(sql, params):
    """Query the Superset metadata DB (respects the configured backend).
    Returns a list of row tuples, or None on any failure."""
    try:
        from superset import db
        from sqlalchemy import text
        rows = db.session.execute(text(sql), params).fetchall()
        return [tuple(r) for r in rows]
    except Exception:
        try:
            from superset import db as _db
            _db.session.rollback()
        except Exception:
            pass
        return None

def _cpi_slice_is_cruise(slice_id):
    try:
        if not slice_id:
            return False
        sid = int(slice_id)
    except Exception:
        return False
    if sid in _cpi_slice_cruise_cache:
        return _cpi_slice_cruise_cache[sid]
    result = False
    rows = _cpi_md_execute("SELECT perm FROM slices WHERE id = :id", {"id": sid})
    if rows:
        perm = (rows[0][0] or "").lower()
        result = any(m in perm for m in _CPI_CRUISE_MARKERS)
    _cpi_slice_cruise_cache[sid] = result
    return result

def _cpi_embed_is_cruise(uuid_str):
    global _cpi_embed_uuid_map
    try:
        if not uuid_str:
            return False
        key = uuid_str.replace("-", "").strip().lower()
        if _cpi_embed_uuid_map is None:
            rows = _cpi_md_execute("SELECT dashboard_id, uuid FROM embedded_dashboards", {})
            if rows is None:
                return False  # transient failure: retry next request
            m = {}
            for did, u in rows:
                if isinstance(u, (bytes, bytearray)):
                    h = u.hex()
                else:
                    h = str(u).replace("-", "").replace("urn:uuid:", "").lower()
                m[h] = did
            _cpi_embed_uuid_map = m
        return _cpi_embed_uuid_map.get(key) in _CPI_CRUISE_DASHBOARD_IDS
    except Exception:
        return False

def _cpi_force_airline_loader(response):
    from flask import request
    try:
        _is_explore = request.path.rstrip("/") == "/explore" and "standalone" in request.args
        _is_embedded = request.path.startswith("/embedded/")
        if not (_is_explore or _is_embedded):
            return response
        if getattr(response, "direct_passthrough", False):
            return response
        if "text/html" not in response.headers.get("Content-Type", ""):
            return response
        body = response.get_data(as_text=True)
        if 'id="cpi-loader"' in body or "</head>" not in body:
            return response
        if _is_explore:
            is_cruise = _cpi_slice_is_cruise(request.args.get("slice_id"))
        elif _is_embedded:
            _emb_uuid = request.path.rstrip("/").rsplit("/", 1)[-1]
            is_cruise = _cpi_embed_is_cruise(_emb_uuid)
        else:
            is_cruise = False
        loader_url = _CPI_SHIP_DATA_URI if is_cruise else _CPI_AIRPLANE_DATA_URI
        style = (
            '<style id="cpi-loader">'
            "img.loading, img.loading.floating { "
            "content: url('%s') !important; } </style>" % loader_url
        )
        response.set_data(body.replace("</head>", style + "</head>", 1))
    except Exception:
        pass
    return response


def FLASK_APP_MUTATOR(app):
    app.after_request(_no_cache_for_patched_chunks)
    app.after_request(_cpi_force_airline_loader)


